"""
Climate Trend Analyzer - Synthetic Test Fixtures.

Contains strictly synthetic datasets with mathematically known parameters
(slopes, seasonal cycles, and deliberate outlier spikes) designed for
unit testing and algorithmic verification.

CRITICAL NOTICE:
All datasets generated by this module are marked with `is_synthetic = True`
and MUST NEVER be conflated with empirical NOAA or NASA climate observations.
"""

from typing import Tuple, List
import numpy as np
import pandas as pd


def generate_linear_trend_series(
    start_year: int = 1900,
    end_year: int = 2000,
    slope_per_decade: float = 0.20,
    intercept: float = -0.30,
    noise_std: float = 0.05,
    seed: int = 42,
) -> Tuple[pd.DataFrame, dict]:
    """
    Generate synthetic monthly series with an exact known linear slope.

    Slope per year: slope_per_decade / 10.0.
    y(t) = intercept + slope_per_year * (t - start_year) + noise(0, noise_std).
    """
    np.random.seed(seed)
    records = []
    slope_per_year = slope_per_decade / 10.0

    for year in range(start_year, end_year + 1):
        for month in range(1, 13):
            dec_year = year + (month - 0.5) / 12.0
            t_offset = dec_year - start_year
            true_signal = intercept + slope_per_year * t_offset
            noise = np.random.normal(0.0, noise_std)
            anomaly = round(float(true_signal + noise), 4)
            date_str = f"{year}{month:02d}"

            records.append({
                "Date": date_str,
                "Year": year,
                "Month": month,
                "Decimal_Year": dec_year,
                "Anomaly": anomaly,
            })

    df = pd.DataFrame(records)
    metadata = {
        "is_synthetic": True,
        "known_slope_per_decade": slope_per_decade,
        "known_intercept": intercept,
        "noise_std": noise_std,
        "start_year": start_year,
        "end_year": end_year,
    }
    return df, metadata


def generate_anomaly_test_series(
    n_months: int = 240,
    injected_outliers: List[Tuple[int, float]] = None,
    seed: int = 123,
) -> Tuple[pd.DataFrame, List[int]]:
    """
    Generate stationary baseline with deliberate, known extreme outlier spikes injected.

    Args:
        n_months: Number of continuous monthly observations.
        injected_outliers: List of (index, value) tuples where anomalies are placed.
        seed: Random seed.

    Returns:
        Tuple of (DataFrame, list of known outlier indices).
    """
    np.random.seed(seed)
    if injected_outliers is None:
        # Deliberately inject +4.5°C and -4.0°C spikes
        injected_outliers = [(50, 4.5), (120, -4.0), (180, 5.0)]

    base_noise = np.random.normal(loc=0.0, scale=0.3, size=n_months)
    outlier_indices = []

    for idx, spike_val in injected_outliers:
        if 0 <= idx < n_months:
            base_noise[idx] = spike_val
            outlier_indices.append(idx)

    start_year = 2000
    records = []
    for i in range(n_months):
        year = start_year + (i // 12)
        month = (i % 12) + 1
        dec_year = year + (month - 0.5) / 12.0
        records.append({
            "Date": f"{year}{month:02d}",
            "Year": year,
            "Month": month,
            "Decimal_Year": dec_year,
            "Anomaly": round(float(base_noise[i]), 4),
        })

    df = pd.DataFrame(records)
    return df, outlier_indices


def generate_seasonal_test_series(
    n_years: int = 20,
    seasonal_amplitude: float = 1.2,
    seed: int = 77,
) -> pd.DataFrame:
    """
    Generate synthetic series with a strict harmonic sinusoidal seasonal pattern.
    y(t) = amplitude * sin(2 * pi * month / 12) + noise.
    """
    np.random.seed(seed)
    records = []
    start_year = 1990

    for y_idx in range(n_years):
        year = start_year + y_idx
        for month in range(1, 13):
            dec_year = year + (month - 0.5) / 12.0
            season_val = seasonal_amplitude * np.sin(2 * np.pi * (month - 1) / 12.0)
            noise = np.random.normal(0.0, 0.05)
            anomaly = round(float(season_val + noise), 4)

            records.append({
                "Date": f"{year}{month:02d}",
                "Year": year,
                "Month": month,
                "Decimal_Year": dec_year,
                "Anomaly": anomaly,
            })

    return pd.DataFrame(records)
